const items = $input.all();
const grouped = {};

for (const item of items) {
  const data = item.json;
  const userId = data.user_id || data.email || 'default';
  if (!grouped[userId]) {
    grouped[userId] = {
      user_id: userId,
      email: data.email || '',
      alerts: []
    };
  }
  grouped[userId].alerts.push(data);
}

return Object.values(grouped).map(group => ({ json: group }));
